command:
// ==========================================
// ⚙️ LUNAS GEGENSTANDS-AUSWAHL: NURTIS SCHALE (V13 Ready - FW Modus)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (typeof DSK === "undefined" || !globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }

    if (typeof DSK === "undefined" && !globalThis.DSK) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");
    }
    const DSK_FW = globalThis.DSK || DSK; 

    // --- 2. AKTEUR PRÜFEN ---
    const wirkenderActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!wirkenderActor) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Nurtikind!");
    }

    // --- 3. QS & MATHE ERMITTELN ---
    let ermittelteQS = wirkenderActor.getFlag("world", "letzteGabenQS") || 1;
    if (wirkenderActor.getFlag("world", "letzteGabenQS")) {
        await wirkenderActor.unsetFlag("world", "letzteGabenQS"); 
    }

    if (typeof testData !== "undefined") {
        ermittelteQS = Number(testData?.result?.QL || testData?.qualityStep || ermittelteQS);
    }

    const berechneterWert = ermittelteQS / 2;
    const bonus = Math.max(1, Math.round(berechneterWert));

    // --- 4. DATEN DER AHNENGABE ---
    const gabenName = "Nurtis Schale";
    const ahnenName = "Nurti";
    const basisEffektName = `${gabenName} (${ahnenName})`;
    const effectId = `dsk.ahnen.${wirkenderActor.id}.nurti`; 

    const dauerText = `Bis zur nächsten Vollmondnacht`;
    const abschlussText = `Die Schale verliert ihren übernatürlichen Zustand und wird wieder zu einem ganz normalen Behältnis. Nurtis schützende Hand ruht.`;

    const wirkungText = `Die Macht Nurtis durchströmt das Behältnis. Das Nurtikind erhält eine Erleichterung von <b>+${bonus} FW</b> <span style="font-size: 0.85em; font-weight: normal;">(${ermittelteQS}QS/2)</span> auf <i>Kochen</i>. Zudem senkt die Schale die Stufe von Giften in darin befindlichen Nahrungsmitteln um <b>${bonus} Stufen</b>. Nur eine Schale gleichzeitig aktiv.`;

    // --- 5. WIRKUNGSENDE REGISTRIEREN ---
    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("nurtisschale", basisEffektName, abschlussText);
    }

    // --- 6. GEFÄßE AUS DEM INVENTAR FILTERN ---
    let zuDurchsuchendeItems = wirkenderActor.items.filter(i => 
        i.type === "equipment" || i.type === "consumable" || i.type === "loot"
    );

    const gefundeneItems = zuDurchsuchendeItems.filter(i => {
        const nameLower = (i.name || "").toLowerCase();
        return nameLower.includes("schale") || nameLower.includes("gefäß") || nameLower.includes("gefaess");
    });

    let dropdownHtml = "";
    if (gefundeneItems.length > 0) {
        let optionen = gefundeneItems.map(i => `<option value="${i.id}">${i.name}</option>`).join("");
        dropdownHtml = `
            <div style="margin-top: 10px;">
                <label style="font-weight: bold; font-size: 0.9em;">Wähle dein Behältnis:</label>
                <select name="gegenstandId" style="width: 100%; padding: 4px; margin-top: 4px; font-family: 'Signika', sans-serif;">
                    ${optionen}
                </select>
            </div>
        `;
    } else {
        dropdownHtml = `<p style="color: darkred; font-size: 0.9em; margin-top: 8px;"><b>Fehlgeschlagen:</b> Keine Schale und kein Gefäß im Inventar gefunden!</p>`;
    }

    // --- 7. DIALOG IM NEUEN V13 DESIGN (DialogV2) ---
    const dialogResult = await foundry.applications.api.DialogV2.wait({
        window: { title: gabenName },
        position: { width: 420 },
        content: `
            <form>
                <div style="font-family: 'Signika', sans-serif;">
                    ${DSK_FW.UI.Header(gabenName, DSK_FW.Symbol(ahnenName))}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="font-size:0.95em; line-height:1.35;">${wirkungText}</p>
                        ${dropdownHtml}
                        <hr style="margin: 10px 0;">
                        <p style="text-align:center; font-weight:bold;">Wirkungsdauer: ${dauerText}</p>
                    </div>
                </div>
            </form>
        `,
        rejectClose: false,
        buttons: gefundeneItems.length > 0 ? [
            {
                action: "anwenden",
                label: "Gabe wirken",
                icon: "fas fa-magic",
                default: true,
                callback: (event) => {
                    const form = event.target.closest("form");
                    return form ? new FormData(form).get("gegenstandId") : null;
                }
            },
            {
                action: "abbrechen",
                label: "Abbrechen",
                icon: "fas fa-times",
                callback: () => false
            }
        ] : [
            {
                action: "abbrechen",
                label: "Schließen",
                icon: "fas fa-times",
                callback: () => false
            }
        ]
    });

    // --- 8. EFFEKT ANWENDEN WENN BESTÄTIGT ---
    if (dialogResult !== false && dialogResult !== undefined) {
        let gewaehltesItemName = "Schale";
        const itemId = dialogResult;

        if (itemId) {
            const itemObj = wirkenderActor.items.get(itemId);
            if (itemObj) gewaehltesItemName = itemObj.name;
        }

        let effektBild = null;
        const gabenItem = wirkenderActor.items.find(i => i.name.includes("Nurtis Schale") || i.name.includes("Nurti Schale"));
        if (gabenItem) effektBild = gabenItem.img;
        if (!effektBild) effektBild = DSK_FW.Symbol(ahnenName);

        for (let ef of wirkenderActor.effects) {
            if (ef.flags?.dsk?.ahnenId === effectId) await ef.delete();
        }

        const finalerEffektName = `${basisEffektName} - ${gewaehltesItemName}`;

        // HIER WURDE FP ZU FW GEÄNDERT: Jetzt wird der Fertigkeitswert korrekt modifiziert
        const changes = [
            { key: "system.skillModifiers.FW", mode: 0, value: `Kochen ${bonus}`, priority: 20 },
            { key: "system.creatureBonus",     mode: 0, value: `Gift -${bonus} Stufen`, priority: 20 }
        ];

        await wirkenderActor.createEmbeddedDocuments("ActiveEffect", [{
            name: finalerEffektName,
            icon: effektBild,
            origin: wirkenderActor.uuid,
            description: wirkungText, 
            flags: { dsk: { ahnenId: effectId, casterUuid: wirkenderActor.uuid, qs: ermittelteQS, ziel: gewaehltesItemName } },
            changes: changes
        }]);

        const chatHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalerEffektName, DSK_FW.Symbol(ahnenName))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="font-size:0.95em; line-height:1.35;">${wirkungText}</p>
                    <hr style="margin: 10px 0;">
                    <p><b>Geweihtes Behältnis:</b> ${gewaehltesItemName}</p>
                    <hr style="margin: 10px 0;">
                    <p style="text-align:center; font-weight:bold;">Wirkungsdauer: ${dauerText}</p>
                </div>
            </div>
        `;

        let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
        Object.entries(wirkenderActor.ownership || wirkenderActor.permission || {})
            .filter(([id, lvl]) => lvl === 3 && id !== "default")
            .forEach(([id]) => ownerIds.add(id));
        const whisperEmpfaenger = Array.from(ownerIds).filter(id => game.users.get(id));

        await ChatMessage.create({
            speaker: { alias: "System" }, 
            content: chatHtml,
            whisper: whisperEmpfaenger 
        });
    }
})();
